// Generates packages/core/src/generated/* from the registry JSON and the rsd/1 schema.
//   node scripts/gen-core.mjs          write the generated files
//   node scripts/gen-core.mjs --check  exit 1 if the committed files differ (CI drift check)
// The registry and the schema are the source of truth; the generated modules let the parser run in a browser
// under a strict CSP (the schema validator is precompiled, so nothing calls eval or new Function at runtime).
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";
import * as prettier from "prettier";

const root = fileURLToPath(new URL("..", import.meta.url));
const core = `${root}/packages/core`;
const check = process.argv.includes("--check");

const readJson = (path) => JSON.parse(readFileSync(path, "utf8"));
const header = (what) =>
  `// GENERATED by scripts/gen-core.mjs from ${what}. Do not edit; run \`pnpm gen\`.\n`;

/** Loads, schema-validates and cross-checks every registry entry. Throws with every problem found. */
export function loadRegistry() {
  const ajv = new Ajv2020({ allErrors: true, strict: true, allowUnionTypes: true });
  const validateEntry = ajv.compile(readJson(`${core}/schema/registry.json`));
  const files = readdirSync(`${core}/registry`)
    .filter((f) => f.endsWith(".json"))
    .sort();
  const problems = [];
  const entries = files.map((file) => {
    const entry = readJson(`${core}/registry/${file}`);
    if (!validateEntry(entry)) {
      for (const e of validateEntry.errors) problems.push(`${file}${e.instancePath}: ${e.message}`);
      return entry;
    }
    if (`${entry.type}.json` !== file)
      problems.push(`${file}: type "${entry.type}" does not match the file name`);
    const text = (v) => String(v);
    for (const [key, def] of Object.entries(entry.states)) {
      if (!def.values.some((v) => v === def.default))
        problems.push(`${file}: default of ${key} not in values`);
    }
    const checkFrom = (where, from, map) => {
      const def = entry.states[from];
      if (!def) return problems.push(`${file}: ${where} maps from unknown state "${from}"`);
      for (const v of def.values) {
        if (!(text(v) in map)) problems.push(`${file}: ${where} has no mapping for ${from}=${text(v)}`);
      }
      for (const k of Object.keys(map)) {
        if (!def.values.some((v) => text(v) === k))
          problems.push(`${file}: ${where} maps unknown value ${k}`);
      }
    };
    for (const mapping of [entry.bedrock, entry.java]) {
      if (!mapping) continue;
      if (typeof mapping.id !== "string") checkFrom("id", mapping.id.from, mapping.id.map);
      const allStates = { ...mapping.states, ...(mapping.upper?.states ?? {}) };
      for (const [name, sm] of Object.entries(allStates)) if ("from" in sm) checkFrom(name, sm.from, sm.map);
    }
    if (entry.needsSupport && "byState" in entry.needsSupport) {
      checkFrom("needsSupport", entry.needsSupport.byState, entry.needsSupport.map);
    }
    for (const w of entry.faces.bedrock.when ?? []) {
      for (const [key, value] of Object.entries(w.states)) {
        if (!entry.states[key]?.values.includes(value))
          problems.push(`${file}: faces.when names ${key}=${value}, not a state value`);
      }
    }
    return entry;
  });
  if (problems.length > 0) throw new Error(`Registry problems:\n  ${problems.join("\n  ")}`);
  return entries;
}

async function format(code) {
  const config = (await prettier.resolveConfig(`${core}/src/generated/x.ts`)) ?? {};
  return prettier.format(code, { ...config, parser: "typescript" });
}

/** Renders every generated file; returns a map of file name to content. */
export async function generate() {
  const out = {};
  const entries = loadRegistry();
  out["registry.ts"] = await format(
    `${header("packages/core/registry/*.json")}import type { RegistryEntry } from "../registry-types.js";\n\n` +
      `/** Every registry entry, sorted by type. */\nexport const REGISTRY_ENTRIES: readonly RegistryEntry[] = ${JSON.stringify(entries)};\n`,
  );

  const schema = readJson(`${core}/schema/rsd-1.json`);
  // unicode: false makes length checks use .length, so the standalone code needs no ajv runtime import.
  const ajv = new Ajv2020({
    allErrors: true,
    strict: true,
    code: { source: true, esm: true },
    unicode: false,
    logger: false,
  });
  const validate = ajv.compile(schema);
  let code = standaloneCode(ajv, validate);
  if (/\brequire\(|from "ajv/.test(code)) throw new Error("standalone validator imports the ajv runtime");
  out["validate-rsd.ts"] = await format(
    `${header("packages/core/schema/rsd-1.json")}// @ts-nocheck\n${code}`,
  );
  out["schema.ts"] = await format(
    `${header("packages/core/schema/rsd-1.json")}\n/** The rsd/1 JSON Schema, as published at /schema/rsd-1.json. */\nexport const RSD_1_SCHEMA = ${JSON.stringify(schema)} as const;\n`,
  );
  return out;
}

async function main() {
  const files = await generate();
  let drift = false;
  for (const [name, content] of Object.entries(files)) {
    const path = `${core}/src/generated/${name}`;
    let current = "";
    try {
      current = readFileSync(path, "utf8");
    } catch {
      // missing file counts as drift
    }
    if (current === content) continue;
    if (check) {
      console.error(`drift: packages/core/src/generated/${name} is out of date; run pnpm gen`);
      drift = true;
    } else {
      writeFileSync(path, content);
      console.log(`wrote packages/core/src/generated/${name}`);
    }
  }
  if (drift) process.exitCode = 1;
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) await main();
